const clock = new THREE.Clock();

// Light cosmic background per quality policy
scene.background = new THREE.Color(0xe8eef2);
scene.fog = new THREE.FogExp2(0xe8eef2, 0.015);

renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Cinematic lighting setup - balanced for light background
const ambientLight = new THREE.AmbientLight(0xddeeff, 0.6);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xfff8f0, 1.2);
keyLight.position.set(8, 12, 6);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.near = 0.1;
keyLight.shadow.camera.far = 50;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xcce0ff, 0.4);
fillLight.position.set(-6, 4, 8);

const rimLight = new THREE.DirectionalLight(0xffffff, 0.8);
rimLight.position.set(0, 5, -10);

scene.add(keyLight, fillLight, rimLight);

// Star system group
const starSystem = new THREE.Group();
scene.add(starSystem);

// Star core - high detail sphere
const coreGeometry = new THREE.SphereGeometry(1, 64, 32);
const coreMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xff3300,
  emissive: 0xff2200,
  emissiveIntensity: 0.2,
  metalness: 0.1,
  roughness: 0.4,
  clearcoat: 1.0,
  clearcoatRoughness: 0.1,
  transmission: 0.2,
  thickness: 1.0
});
const starCore = new THREE.Mesh(coreGeometry, coreMaterial);
starCore.castShadow = true;
starSystem.add(starCore);

// Atmospheric glow layers (additive blending for volumetric feel)
const glowLayers = [];
const glowConfigs = [
  { radius: 1.4, color: 0xff6600, opacity: 0.3, segments: 48 },
  { radius: 1.8, color: 0xffaa44, opacity: 0.15, segments: 32 },
  { radius: 2.4, color: 0xffdd88, opacity: 0.08, segments: 32 }
];

glowConfigs.forEach(config => {
  const geo = new THREE.SphereGeometry(config.radius, config.segments, config.segments / 2);
  const mat = new THREE.MeshBasicMaterial({
    color: config.color,
    transparent: true,
    opacity: config.opacity,
    side: THREE.BackSide,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.visible = false;
  glowLayers.push(mesh);
  starSystem.add(mesh);
});

// Corona particles (solar flares/prominences)
const particleCount = 800;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);
const particleVelocities = new Float32Array(particleCount * 3);
const particleOrigins = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = 1.1 + Math.random() * 0.5;

  particlePositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  particlePositions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  particlePositions[i * 3 + 2] = r * Math.cos(phi);

  particleOrigins[i * 3] = particlePositions[i * 3];
  particleOrigins[i * 3 + 1] = particlePositions[i * 3 + 1];
  particleOrigins[i * 3 + 2] = particlePositions[i * 3 + 2];

  particleVelocities[i * 3] = (Math.random() - 0.5) * 0.02;
  particleVelocities[i * 3 + 1] = (Math.random() - 0.5) * 0.02;
  particleVelocities[i * 3 + 2] = (Math.random() - 0.5) * 0.02;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0xffaa55,
  size: 0.08,
  transparent: true,
  opacity: 0,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending
});
const coronaParticles = new THREE.Points(particleGeo, particleMat);
starSystem.add(coronaParticles);

// Accretion disk (protoplanetary disk)
const diskGeometry = new THREE.RingGeometry(2.5, 4.5, 128, 1, 0, Math.PI * 2);
const diskMaterial = new THREE.MeshStandardMaterial({
  color: 0x88aabb,
  transparent: true,
  opacity: 0.4,
  side: THREE.DoubleSide,
  roughness: 0.8,
  metalness: 0.2
});
const accretionDisk = new THREE.Mesh(diskGeometry, diskMaterial);
accretionDisk.rotation.x = Math.PI / 2;
accretionDisk.receiveShadow = true;
starSystem.add(accretionDisk);

// Star light source (intensity grows with birth)
const starLight = new THREE.PointLight(0xffaa55, 0, 20);
starLight.position.set(0, 0, 0);
