// Dust/Debris field
const dustCount = 600;
const dustGeo = new THREE.BufferGeometry();
const dustPositions = new Float32Array(dustCount * 3);
const dustSizes = new Float32Array(dustCount);

for (let i = 0; i < dustCount; i++) {
  const angle = Math.random() * Math.PI * 2;
  const radius = 3 + Math.random() * 8;
  const height = (Math.random() - 0.5) * 1.5;

  dustPositions[i * 3] = Math.cos(angle) * radius;
  dustPositions[i * 3 + 1] = height;
  dustPositions[i * 3 + 2] = Math.sin(angle) * radius;
  dustSizes[i] = Math.random() * 0.1 + 0.02;
}

dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPositions, 3));
dustGeo.setAttribute('size', new THREE.BufferAttribute(dustSizes, 1));

const dustMat = new THREE.PointsMaterial({
  color: 0xaaccdd,
  size: 0.15,
  transparent: true,
  opacity: 0.6,
  sizeAttenuation: true
});
const dustField = new THREE.Points(dustGeo, dustMat);
scene.add(dustField);

// Birth progress tracking
let birthProgress = 0;
const birthDuration = 12; // seconds to reach 100%

// Camera setup
camera.position.set(6, 4, 8);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 3;
controls.maxDistance = 20;
controls.target.set(0, 0, 0);

// Animation easing function (easeInOutCubic)
function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function updateStarBirth(delta) {
  // Update progress
  if (birthProgress < 1.0) {
    birthProgress += delta / birthDuration;
    birthProgress = Math.min(birthProgress, 1.0);
  }

  const eased = easeInOutCubic(birthProgress);

  // Phase 1: Contraction (0-0.3) - Core heats up, shrinks slightly then expands
  // Phase 2: Ignition (0.3-0.7) - Rapid brightening, color shift
  // Phase 3: Stabilization (0.7-1.0) - Final glow, steady state

  // Core transformations
  const targetScale = 1.0 + (eased * 0.3); // Grows 30%
  starCore.scale.setScalar(targetScale);

  // Color temperature shift: Red (0xff3300) -> Yellow (0xffdd00) -> White (0xffffee)
  const r = 1.0;
  const g = 0.2 + (eased * 0.8);
  const b = eased * 0.93;
  const color = new THREE.Color(r, Math.min(g, 1.0), Math.min(b, 1.0));

  coreMaterial.color.lerpColors(new THREE.Color(0xff3300), new THREE.Color(0xffffee), eased);
  coreMaterial.emissive.lerpColors(new THREE.Color(0xff2200), new THREE.Color(0xffaa55), eased);
  coreMaterial.emissiveIntensity = 0.2 + (eased * 2.0);

  // Light intensity follows birth
  starLight.intensity = eased * 3.5;
  starLight.color.copy(color);

  // Glow layers activation sequence
  glowLayers.forEach((layer, index) => {
    const threshold = index * 0.25;
    if (birthProgress > threshold) {
      layer.visible = true;
      const localProgress = Math.min((birthProgress - threshold) / 0.4, 1.0);
      layer.material.opacity = config[index].opacity * localProgress;
      layer.scale.setScalar(1.0 + (localProgress * 0.2));
    }
  });

  // Corona particles appear during ignition
  if (birthProgress > 0.4) {
    const coronaProgress = (birthProgress - 0.4) / 0.6;
    particleMat.opacity = coronaProgress * 0.8;

    // Animate corona turbulence
    const positions = particleGeo.attributes.position.array;
    const time = clock.getElapsedTime();

    for (let i = 0; i < particleCount; i++) {
      const idx = i * 3;
      const origX = particleOrigins[idx];
      const origY = particleOrigins[idx + 1];
      const origZ = particleOrigins[idx + 2];

      const noise = Math.sin(time * 2 + i * 0.1) * 0.1 * coronaProgress;
      positions[idx] = origX + particleVelocities[idx] * time * 10 + noise;
      positions[idx + 1] = origY + particleVelocities[idx + 1] * time * 10 + noise;
      positions[idx + 2] = origZ + particleVelocities[idx + 2] * time * 10 + noise;
    }
    particleGeo.attributes.position.needsUpdate = true;
  }

  // Accretion disk fades as star brightens (material blows away)
  accretionDisk.material.opacity = 0.4 * (1.0 - eased * 0.7);
  accretionDisk.rotation.z += delta * 0.1;

  // Dust field rotation
  dustField.rotation.y += delta * 0.02;

  // Completion pulse at 100%
  if (birthProgress >= 1.0) {
    const pulse = 1.0 + Math.sin(clock.getElapsedTime() * 3) * 0.02;
    starCore.scale.setScalar(targetScale * pulse);
    starLight.intensity = 3.5 + Math.sin(clock.getElapsedTime() * 3) * 0.2;
  }
}

// Store glow configs reference
const config = glowConfigs;

function animate() {
  requestAnimationFrame(animate);

  const delta = clock.getDelta();
  updateStarBirth(delta);

  // Slow rotation of entire system for cinematic effect
  starSystem.rotation.y += delta * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();

