function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  coilGroup.rotation.z = t * 0.12;
  coilGroup.rotation.x = Math.sin(t * 0.25) * 0.05;

  fieldGroup.rotation.z = -t * 0.18;
  const fieldPulse = 1 + Math.sin(t * 3) * 0.03;
  fieldGroup.scale.set(fieldPulse, fieldPulse, fieldPulse);

  const corePulse = 1 + Math.sin(t * 4) * 0.06;
  plasmaCore.scale.set(corePulse, corePulse, corePulse);
  plasmaCore.material.emissiveIntensity = 2.5 + Math.sin(t * 6) * 0.7;
  plasmaGlow.scale.setScalar(1 + Math.sin(t * 2.5) * 0.04);

  const positions = alphaParticles.geometry.attributes.position.array;
  for (let i = 0; i < productCount; i++) {
    const idx = i * 3;
    positions[idx] += productVel[i].x;
    positions[idx + 1] += productVel[i].y;
    positions[idx + 2] += productVel[i].z;

    const distSq = positions[idx]**2 + positions[idx+1]**2 + positions[idx+2]**2;
    if (distSq > 36) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const r = 1.3 + Math.random() * 0.3;
      positions[idx] = r * Math.sin(phi) * Math.cos(theta);
      positions[idx + 1] = r * Math.sin(phi) * Math.sin(theta);
      positions[idx + 2] = r * Math.cos(phi);
    }
  }
  alphaParticles.geometry.attributes.position.needsUpdate = true;
  alphaParticles.rotation.y = t * 0.08;

  dust.rotation.y = t * 0.02;
  dust.position.y = Math.sin(t * 0.4) * 0.3;

  controls.update();
  renderer.render(scene, camera);
}

