  fuelParticles.geometry.attributes.position.needsUpdate = true;

  const pPositions = productParticles.geometry.attributes.position.array;
  for (let i = 0; i < productCount; i++) {
    const pd = prodData[i];
    pPositions[i * 3] += pd.vx;
    pPositions[i * 3 + 1] += pd.vy;
    pPositions[i * 3 + 2] += pd.vz;

    const dist = Math.sqrt(
      pPositions[i * 3] ** 2 + 
      pPositions[i * 3 + 1] ** 2 + 
      pPositions[i * 3 + 2] ** 2
    );

    if (dist > 7) {
      pPositions[i * 3] = (Math.random() - 0.5) * 0.6;
      pPositions[i * 3 + 1] = (Math.random() - 0.5) * 0.6;
      pPositions[i * 3 + 2] = (Math.random() - 0.5) * 0.6;
    }
  }
  productParticles.geometry.attributes.position.needsUpdate = true;
  productParticles.rotation.y = t * 0.05;

  controls.update();
  renderer.render(scene, camera);
}
