// Animation loop
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  // Rotate magnetic coils
  coilGroup.rotation.x = t * 0.3;
  coilGroup.rotation.y = t * 0.2;
  coilGroup.rotation.z = t * 0.1;

  // Pulse plasma core
  const pulse = 1 + Math.sin(t * 4) * 0.15 + Math.sin(t * 12) * 0.05;
  plasmaCore.scale.setScalar(pulse);
  plasmaCore.material.emissiveIntensity = 2.0 + Math.sin(t * 3) * 0.5;
  halo.scale.setScalar(1 + Math.sin(t * 2) * 0.1);
  halo.material.opacity = 0.1 + Math.sin(t * 3) * 0.05;

  // Beam intensity modulation
  pBeam.material.opacity = 0.4 + Math.sin(t * 8) * 0.2;
  bBeam.material.opacity = 0.4 + Math.cos(t * 8) * 0.2;

  // Animate alpha particles (fusion products)
  const positions = alphaParticles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    const idx = i * 3;
    const vel = alphaVelocities[i];

    // Spiral motion influenced by magnetic field
    const spiralRadius = 0.02 * (alphaLife[i] / 100);
    vel.spiral += 0.1;

    positions[idx] += vel.x + Math.cos(vel.spiral) * spiralRadius;
    positions[idx + 1] += vel.y + Math.sin(vel.spiral) * 0.01;
    positions[idx + 2] += vel.z + Math.sin(vel.spiral) * spiralRadius;

    alphaLife[i]--;

    // Reset particle when life ends or too far
    const dist = Math.sqrt(
      positions[idx]**2 + 
      positions[idx + 1]**2 + 
      positions[idx + 2]**2
    );

    if (alphaLife[i] <= 0 || dist > 8) {
      positions[idx] = (Math.random() - 0.5) * 0.3;
      positions[idx + 1] = (Math.random() - 0.5) * 0.3;
      positions[idx + 2] = (Math.random() - 0.5) * 0.3;
      alphaLife[i] = 80 + Math.random() * 60;
    }
  }
  alphaParticles.geometry.attributes.position.needsUpdate = true;
  alphaParticles.rotation.y = t * 0.5;

  // Pulse rings expansion
  pulseRings.forEach((pr, i) => {
    const scale = 1 + ((t + pr.offset) % 3) * 0.8;
    pr.mesh.scale.setScalar(scale);
    pr.mesh.material.opacity = Math.max(0, 0.4 - ((t + pr.offset) % 3) * 0.15);
    pr.mesh.rotation.x = Math.PI / 2 + Math.sin(t + i) * 0.2;
    pr.mesh.rotation.y = Math.cos(t * 0.5 + i) * 0.3;
  });

  // Subtle chamber rotation
  heroGroup.rotation.y = Math.sin(t * 0.1) * 0.1;
  heroGroup.rotation.z = Math.cos(t * 0.15) * 0.05;

  // Dynamic rim light intensity
  rimLight.intensity = 1.0 + Math.sin(t * 2) * 0.3;

  controls.update();
  renderer.render(scene, camera);
}

