// Animation easing function (easeInOutCubic)
function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function updateStarBirth(delta) {
  // Update progress
  if (birthProgress < 1.0) {
    birthProgress += delta / birthDuration;
    birthProgress = Math.min(birthProgress, 1.0);
  }

  const eased = easeInOutCubic(birthProgress);

  // Phase 1: Contraction (0-0.3) - Core heats up, shrinks slightly then expands
  // Phase 2: Ignition (0.3-0.7) - Rapid brightening, color shift
  // Phase 3: Stabilization (0.7-1.0) - Final glow, steady state

  // Core transformations
  const targetScale = 1.0 + (eased * 0.3); // Grows 30%
  starCore.scale.setScalar(targetScale);

