  const r = 1.0;
  const g = 0.2 + (eased * 0.8);
  const b = eased * 0.93;
  const color = new THREE.Color(r, Math.min(g, 1.0), Math.min(b, 1.0));

  coreMaterial.color.lerpColors(new THREE.Color(0xff3300), new THREE.Color(0xffffee), eased);
  coreMaterial.emissive.lerpColors(new THREE.Color(0xff2200), new THREE.Color(0xffaa55), eased);
  coreMaterial.emissiveIntensity = 0.2 + (eased * 2.0);

  // Light intensity follows birth
  starLight.intensity = eased * 3.5;
  starLight.color.copy(color);

  // Glow layers activation sequence
