  }

  // Accretion disk fades as star brightens (material blows away)
  accretionDisk.material.opacity = 0.4 * (1.0 - eased * 0.7);
  accretionDisk.rotation.z += delta * 0.1;

  // Dust field rotation
  dustField.rotation.y += delta * 0.02;

  // Completion pulse at 100%
  if (birthProgress >= 1.0) {
    const pulse = 1.0 + Math.sin(clock.getElapsedTime() * 3) * 0.02;
    starCore.scale.setScalar(targetScale * pulse);
    starLight.intensity = 3.5 + Math.sin(clock.getElapsedTime() * 3) * 0.2;
  }
}

