  reactorGroup.rotation.y = t * 0.1;
  reactorGroup.rotation.x = Math.sin(t * 0.15) * 0.03;
  fieldLine.rotation.x = t * 0.25;

  plasmaMat.emissiveIntensity = 1.6 + Math.sin(t * 5) * 0.5;
  coreMat.emissiveIntensity = 2.8 + Math.sin(t * 4) * 0.7;
  rimLight.intensity = 0.8 + Math.sin(t * 2) * 0.2;

  const fPositions = fuelParticles.geometry.attributes.position.array;
  for (let i = 0; i < fuelCount; i++) {
    const d = fuelData[i];
    d.angle += d.speed * 0.012;
    fPositions[i * 3] = Math.cos(d.angle) * d.radius;
    fPositions[i * 3 + 2] = Math.sin(d.angle) * d.radius;
    fPositions[i * 3 + 1] = d.yBase + Math.sin(t * 2 + d.phase) * 0.12;
  }
  fuelParticles.geometry.attributes.position.needsUpdate = true;

  const pPositions = productParticles.geometry.attributes.position.array;
  for (let i = 0; i < productCount; i++) {
    const pd = prodData[i];
    pPositions[i * 3] += pd.vx;
    pPositions[i * 3 + 1] += pd.vy;
    pPositions[i * 3 + 2] += pd.vz;

    const dist = Math.sqrt(
      pPositions[i * 3] ** 2 + 
      pPositions[i * 3 + 1] ** 2 + 
      pPositions[i * 3 + 2] ** 2
    );

    if (dist > 7) {
      pPositions[i * 3] = (Math.random() - 0.5) * 0.6;
      pPositions[i * 3 + 1] = (Math.random() - 0.5) * 0.6;
      pPositions[i * 3 + 2] = (Math.random() - 0.5) * 0.6;
    }
  }
  productParticles.geometry.attributes.position.needsUpdate = true;
  productParticles.rotation.y = t * 0.05;

  controls.update();
  renderer.render(scene, camera);
}
