// Generate base pair sequence (A-T, G-C alternating to show pairing rules)
const baseSequence = ['A', 'G', 'T', 'C', 'A', 'G', 'T', 'C', 'A', 'T', 'G', 'C'];

const backbonePoints1 = [];
const backbonePoints2 = [];

// Create DNA structure
for (let i = 0; i < totalBasePairs; i++) {
  const t = i / totalBasePairs;
  const angle = t * Math.PI * 2 * turns;
  const y = (t - 0.5) * helixHeight;

  // Calculate backbone positions (sugar-phosphate)
  const x1 = Math.cos(angle) * helixRadius;
  const z1 = Math.sin(angle) * helixRadius;
  const x2 = Math.cos(angle + Math.PI) * helixRadius;
  const z2 = Math.sin(angle + Math.PI) * helixRadius;

  backbonePoints1.push(new THREE.Vector3(x1, y, z1));
  backbonePoints2.push(new THREE.Vector3(x2, y, z2));

  // Replication fork effect: gradually separate strands at the top 15%
  let separationOffset = 0;
  if (t > 0.85) {
    separationOffset = (t - 0.85) * 8; // Gradual separation
  }

  const adjustedY1 = y + separationOffset * 0.5;
  const adjustedY2 = y - separationOffset * 0.5;

  // Backbone nodes (deoxyribose sugars)
  const sugarGeo = new THREE.SphereGeometry(0.28, 32, 16);
  const sugar1 = new THREE.Mesh(sugarGeo, backboneMaterial);
  const sugar2 = new THREE.Mesh(sugarGeo, backboneMaterial);

  sugar1.position.set(x1, adjustedY1, z1);
  sugar2.position.set(x2, adjustedY2, z2);

  sugar1.castShadow = true;
  sugar1.receiveShadow = true;
  sugar2.castShadow = true;
  sugar2.receiveShadow = true;

  dnaGroup.add(sugar1);
  dnaGroup.add(sugar2);

  // Base pairs (nucleotides)
  const baseType1 = baseSequence[i % baseSequence.length];
  const baseType2 = baseType1 === 'A' ? 'T' : 
                   baseType1 === 'T' ? 'A' : 
                   baseType1 === 'G' ? 'C' : 'G';

  const midX = (x1 + x2) / 2;
  const midZ = (z1 + z2) / 2;
  const midY = (adjustedY1 + adjustedY2) / 2;

  // Create nucleotide bases (geometric representation)
  const baseGeo = new THREE.CapsuleGeometry(0.12, 0.9, 4, 16);

  const base1 = new THREE.Mesh(baseGeo, baseMaterials[baseType1]);
  const base2 = new THREE.Mesh(baseGeo, baseMaterials[baseType2]);

  // Position bases between sugar and center
  base1.position.set((x1 + midX) / 2, (adjustedY1 + midY) / 2, (z1 + midZ) / 2);
  base2.position.set((x2 + midX) / 2, (adjustedY2 + midY) / 2, (z2 + midZ) / 2);

  // Orient bases toward center
  base1.lookAt(midX, midY, midZ);
  base2.lookAt(midX, midY, midZ);

  base1.castShadow = true;
  base2.castShadow = true;

  dnaGroup.add(base1);
  dnaGroup.add(base2);

  // Hydrogen bonds (visualizing A-T: 2 bonds, G-C: 3 bonds)
  const bondCount = (baseType1 === 'A' || baseType1 === 'T') ? 2 : 3;
  const bondGeo = new THREE.CylinderGeometry(0.03, 0.03, 0.15, 8);

  for (let b = 0; b < bondCount; b++) {
    const bond = new THREE.Mesh(bondGeo, hydrogenBondMaterial);
    const offset = (b - (bondCount - 1) / 2) * 0.25;

    bond.position.set(midX + offset * Math.cos(angle), midY, midZ + offset * Math.sin(angle));
    bond.rotation.z = Math.PI / 2;
    bond.rotation.y = -angle;

    dnaGroup.add(bond);
  }
}

