keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 40;
keyLight.shadow.camera.left = -10;
keyLight.shadow.camera.right = 10;
keyLight.shadow.bias = -0.0005;

const fillLight = new THREE.DirectionalLight(0xd4e4ff, 0.8);
fillLight.position.set(-8, 6, 6);

const rimLight = new THREE.SpotLight(0xffffff, 1.2);
rimLight.position.set(0, 8, -8);
rimLight.lookAt(0, 0, 0);

const ambientLight = new THREE.AmbientLight(0xe8eef5, 0.6);
scene.add(ambientLight, keyLight, fillLight, rimLight);

const dnaGroup = new THREE.Group();
scene.add(dnaGroup);

const baseColors = {
  A: 0x4ade80,
  T: 0xf87171,
  G: 0x60a5fa,
  C: 0xfbbf24
};

const sequence = ['A', 'T', 'G', 'C', 'A', 'T', 'C', 'G', 'G', 'C', 'A', 'T', 'A', 'T', 'G', 'C'];
const helixRadius = 1.2;
const risePerBase = 0.6;
const twistPerBase = 0.6;
const baseCount = sequence.length;

const backboneMat = new THREE.MeshPhysicalMaterial({
  color: 0x94a3b8,
  metalness: 0.1,
  roughness: 0.2,
  clearcoat: 0.3,
  clearcoatRoughness: 0.1
});

const backboneGeo = new THREE.SphereGeometry(0.14, 32, 16);
const baseGeo = new THREE.SphereGeometry(0.12, 32, 16);
const connectorGeo = new THREE.CylinderGeometry(0.06, 0.06, 1, 16);

connectorGeo.rotateZ(Math.PI / 2);

for (let i = 0; i < baseCount; i++) {
  const t = i * twistPerBase;
  const y = (i - baseCount / 2) * risePerBase;

  const x1 = Math.cos(t) * helixRadius;
  const z1 = Math.sin(t) * helixRadius;
  const x2 = Math.cos(t + Math.PI) * helixRadius;
  const z2 = Math.sin(t + Math.PI) * helixRadius;

  const backbone1 = new THREE.Mesh(backboneGeo, backboneMat);
  backbone1.position.set(x1, y, z1);
  backbone1.castShadow = true;
  backbone1.receiveShadow = true;
  dnaGroup.add(backbone1);

  const backbone2 = new THREE.Mesh(backboneGeo, backboneMat);
  backbone2.position.set(x2, y, z2);
  backbone2.castShadow = true;
  backbone2.receiveShadow = true;
  dnaGroup.add(backbone2);

  if (i < baseCount - 1) {
    const tNext = (i + 1) * twistPerBase;
    const yNext = (i + 1 - baseCount / 2) * risePerBase;

    const x1Next = Math.cos(tNext) * helixRadius;
    const z1Next = Math.sin(tNext) * helixRadius;

    const strand1Geo = new THREE.CylinderGeometry(0.08, 0.08, Math.sqrt(
      Math.pow(x1Next - x1, 2) + Math.pow(yNext - y, 2) + Math.pow(z1Next - z1, 2)
    ), 8);

    const strand1 = new THREE.Mesh(strand1Geo, new THREE.MeshStandardMaterial({
      color: 0x64748b,
      roughness: 0.4
    }));
    strand1.position.set((x1 + x1Next) / 2, (y + yNext) / 2, (z1 + z1Next) / 2);
    strand1.lookAt(x1Next, yNext, z1Next);
    strand1.rotateX(Math.PI / 2);
    dnaGroup.add(strand1);

    const x2Next = Math.cos(tNext + Math.PI) * helixRadius;
    const z2Next = Math.sin(tNext + Math.PI) * helixRadius;

    const strand2Geo = new THREE.CylinderGeometry(0.08, 0.08, Math.sqrt(
      Math.pow(x2Next - x2, 2) + Math.pow(yNext - y, 2) + Math.pow(z2Next - z2, 2)
    ), 8);

    const strand2 = new THREE.Mesh(strand2Geo, new THREE.MeshStandardMaterial({
      color: 0x64748b,
      roughness: 0.4
    }));
    strand2.position.set((x2 + x2Next) / 2, (y + yNext) / 2, (z2 + z2Next) / 2);
    strand2.lookAt(x2Next, yNext, z2Next);
    strand2.rotateX(Math.PI / 2);
    dnaGroup.add(strand2);
  }

  const base1 = sequence[i];
  const base2 = base1 === 'A' ? 'T' : base1 === 'T' ? 'A' : base1 === 'G' ? 'C' : 'G';

  const base1Mesh = new THREE.Mesh(baseGeo, new THREE.MeshPhysicalMaterial({
    color: baseColors[base1],
    metalness: 0.0,
    roughness: 0.3,
    transmission: 0.2,
    thickness: 0.5,
    clearcoat: 0.5
  }));
  base1Mesh.position.set(x1 * 0.7, y, z1 * 0.7);
  base1Mesh.castShadow = true;
  dnaGroup.add(base1Mesh);

  const base2Mesh = new THREE.Mesh(baseGeo, new THREE.MeshPhysicalMaterial({
    color: baseColors[base2],
    metalness: 0.0,
    roughness: 0.3,
    transmission: 0.2,
    thickness: 0.5,
    clearcoat: 0.5
  }));
  base2Mesh.position.set(x2 * 0.7, y, z2 * 0.7);
  base2Mesh.castShadow = true;
  dnaGroup.add(base2Mesh);

  const distance = Math.sqrt(
    Math.pow(x2 * 0.7 - x1 * 0.7, 2) + Math.pow(z2 * 0.7 - z1 * 0.7, 2)
  );

  const hydrogenBonds = new THREE.Group();
  const bondCount = 2;
  for (let b = 0; b < bondCount; b++) {
    const bond = new THREE.Mesh(
      new THREE.CylinderGeometry(0.02, 0.02, distance / bondCount - 0.05, 8),
      new THREE.MeshStandardMaterial({ color: 0xe2e8f0, emissive: 0x222222 })
    );
    bond.rotateZ(Math.PI / 2);
    bond.position.x = (b - (bondCount - 1) / 2) * (distance / bondCount);
    hydrogenBonds.add(bond);
  }
  hydrogenBonds.position.set((x1 * 0.7 + x2 * 0.7) / 2, y, (z1 * 0.7 + z2 * 0.7) / 2);
  hydrogenBonds.lookAt(x2 * 0.7, y, z2 * 0.7);
  dnaGroup.add(hydrogenBonds);
}

const unzippingGroup = new THREE.Group();
scene.add(unzippingGroup);

for (let i = baseCount; i < baseCount + 4; i++) {
  const t = i * twistPerBase;
  const y = (i - baseCount / 2) * risePerBase;

  const separation = 0.3 * (i - baseCount + 1);

  const x1 = Math.cos(t) * (helixRadius + separation);
  const z1 = Math.sin(t) * helixRadius;
  const x2 = Math.cos(t + Math.PI) * (helixRadius + separation);
  const z2 = Math.sin(t + Math.PI) * helixRadius;

  const backbone1 = new THREE.Mesh(backboneGeo, backboneMat);
  backbone1.position.set(x1, y, z1);
  unzippingGroup.add(backbone1);

  const backbone2 = new THREE.Mesh(backboneGeo, backboneMat);
  backbone2.position.set(x2, y, z2);
  unzippingGroup.add(backbone2);
}

const particleCount = 800;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);
const particleVelocities = [];

for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3] = (Math.random() - 0.5) * 20;
  particlePositions[i * 3 + 1] = (Math.random() - 0.5) * 15;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 20;
  particleVelocities.push({
    x: (Math.random() - 0.5) * 0.01,
    y: (Math.random() - 0.5) * 0.01,
    z: (Math.random() - 0.5) * 0.01
  });
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x3b82f6,
  size: 0.05,
  transparent: true,
  opacity: 0.4,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

const pmremGenerator = new THREE.PMREMGenerator(renderer);
pmremGenerator.compileEquirectangularShader();

const textureLoader = new THREE.TextureLoader();
textureLoader.load('/vendor/env/venice_sunset_1k.hdr', function(texture) {
  const envMap = pmremGenerator.fromEquirectangular(texture).texture;
  scene.environment = envMap;
  texture.dispose();
}, undefined, function() {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createLinearGradient(0, 0, 0, 256);
  gradient.addColorStop(0, '#e0e7ff');
  gradient.addColorStop(1, '#f0f4f8');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 512, 256);
  const fallbackTexture = new THREE.CanvasTexture(canvas);
  fallbackTexture.mapping = THREE.EquirectangularReflectionMapping;
  scene.environment = fallbackTexture;
});

camera.position.set(5, 2, 8);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);
controls.minDistance = 3;
controls.maxDistance = 15;
controls.maxPolarAngle = Math.PI / 1.5;

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  dnaGroup.rotation.y = t * 0.15;
  dnaGroup.position.y = Math.sin(t * 0.5) * 0.2;

  unzippingGroup.rotation.y = t * 0.15;
  unzippingGroup.position.y = dnaGroup.position.y;

  const positions = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    positions[i * 3] += particleVelocities[i].x + Math.sin(t + i) * 0.002;
    positions[i * 3 + 1] += particleVelocities[i].y + Math.cos(t * 0.7 + i) * 0.002;
    positions[i * 3 + 2] += particleVelocities[i].z;

    if (Math.abs(positions[i * 3]) > 10) positions[i * 3] *= -0.9;
    if (Math.abs(positions[i * 3 + 1]) > 8) positions[i * 3 + 1] *= -0.9;
    if (Math.abs(positions[i * 3 + 2]) > 10) positions[i * 3 + 2] *= -0.9;
  }
  particles.geometry.attributes.position.needsUpdate = true;
  particles.rotation.y = t * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();
